import { sparkNextInt, sparkShuffle } from './rng'
import { SPARK_ORBS, type SparkCascade, type SparkCell, type SparkMatchGroup, type SparkOrb } from './types'

export const sparkCellIndex = (cell: SparkCell): number => cell.row * SPARK_RIVAL_BOARD_WIDTH + cell.column
export const sparkIndexCell = (index: number): SparkCell => ({
  row: Math.floor(index / SPARK_RIVAL_BOARD_WIDTH),
  column: index % SPARK_RIVAL_BOARD_WIDTH,
})

function assertBoard(board: readonly SparkOrb[]): void {
  if (board.length !== SPARK_RIVAL_BOARD_SIZE || board.some((orb) => !SPARK_ORBS.includes(orb))) {
    throw new Error(`Spark Rival board must contain ${SPARK_RIVAL_BOARD_SIZE} valid orbs`)
  }
}

function markedMatchIndices(board: readonly SparkOrb[]): Set<number> {
  const marked = new Set<number>()
  for (let row = 0; row < SPARK_RIVAL_BOARD_HEIGHT; row += 1) {
    let start = 0
    while (start < SPARK_RIVAL_BOARD_WIDTH) {
      const first = row * SPARK_RIVAL_BOARD_WIDTH + start
      const orb = board[first]!
      let end = start + 1
      while (end < SPARK_RIVAL_BOARD_WIDTH && board[row * SPARK_RIVAL_BOARD_WIDTH + end] === orb) end += 1
      if (end - start >= 3) for (let column = start; column < end; column += 1) marked.add(row * SPARK_RIVAL_BOARD_WIDTH + column)
      start = end
    }
  }
  for (let column = 0; column < SPARK_RIVAL_BOARD_WIDTH; column += 1) {
    let start = 0
    while (start < SPARK_RIVAL_BOARD_HEIGHT) {
      const first = start * SPARK_RIVAL_BOARD_WIDTH + column
      const orb = board[first]!
      let end = start + 1
      while (end < SPARK_RIVAL_BOARD_HEIGHT && board[end * SPARK_RIVAL_BOARD_WIDTH + column] === orb) end += 1
      if (end - start >= 3) for (let row = start; row < end; row += 1) marked.add(row * SPARK_RIVAL_BOARD_WIDTH + column)
      start = end
    }
  }
  return marked
}

export function sparkMatchGroups(board: readonly SparkOrb[]): SparkMatchGroup[] {
  assertBoard(board)
  const marked = markedMatchIndices(board)
  const groups: SparkMatchGroup[] = []
  while (marked.size > 0) {
    const start = Math.min(...marked)
    const orb = board[start]!
    const pending = [start]
    const indices: number[] = []
    marked.delete(start)
    while (pending.length > 0) {
      const index = pending.pop()!
      indices.push(index)
      const { row, column } = sparkIndexCell(index)
      const neighbours = [
        row > 0 ? index - SPARK_RIVAL_BOARD_WIDTH : -1,
        column > 0 ? index - 1 : -1,
        column + 1 < SPARK_RIVAL_BOARD_WIDTH ? index + 1 : -1,
        row + 1 < SPARK_RIVAL_BOARD_HEIGHT ? index + SPARK_RIVAL_BOARD_WIDTH : -1,
      ]
      for (const neighbour of neighbours) {
        if (neighbour >= 0 && marked.has(neighbour) && board[neighbour] === orb) {
          marked.delete(neighbour)
          pending.push(neighbour)
        }
      }
    }
    groups.push({ orb, indices: indices.sort((left, right) => left - right) })
  }
  return groups.sort((left, right) => left.indices[0]! - right.indices[0]!)
}

export function applySparkPath(board: readonly SparkOrb[], path: readonly SparkCell[]): SparkOrb[] {
  assertBoard(board)
  if (path.length < 2) throw new Error('Spark Rival drag must cross at least one cell')
  const next = [...board]
  for (let offset = 1; offset < path.length; offset += 1) {
    const previous = sparkCellIndex(path[offset - 1]!)
    const current = sparkCellIndex(path[offset]!)
    const held = next[previous]!
    next[previous] = next[current]!
    next[current] = held
  }
  return next
}

function refill(board: readonly SparkOrb[], cleared: ReadonlySet<number>, state: number): { board: SparkOrb[]; state: number } {
  const next = Array<SparkOrb>(SPARK_RIVAL_BOARD_SIZE)
  let nextState = state
  for (let column = 0; column < SPARK_RIVAL_BOARD_WIDTH; column += 1) {
    const survivors: SparkOrb[] = []
    for (let row = SPARK_RIVAL_BOARD_HEIGHT - 1; row >= 0; row -= 1) {
      const index = row * SPARK_RIVAL_BOARD_WIDTH + column
      if (!cleared.has(index)) survivors.push(board[index]!)
    }
    let survivor = 0
    for (let row = SPARK_RIVAL_BOARD_HEIGHT - 1; row >= 0; row -= 1) {
      const index = row * SPARK_RIVAL_BOARD_WIDTH + column
      if (survivor < survivors.length) next[index] = survivors[survivor++]!
      else {
        const [orb, advanced] = sparkNextInt(nextState, SPARK_ORBS.length)
        nextState = advanced
        next[index] = SPARK_ORBS[orb]!
      }
    }
  }
  return { board: next, state: nextState }
}

export function resolveSparkBoard(board: readonly SparkOrb[], state: number): {
  board: readonly SparkOrb[]
  rngState: number
  cascades: readonly SparkCascade[]
} {
  assertBoard(board)
  let nextBoard = [...board]
  let nextState = state
  const cascades: SparkCascade[] = []
  for (let cascade = 0; cascade < SPARK_RIVAL_CASCADE_LIMIT; cascade += 1) {
    const groups = sparkMatchGroups(nextBoard)
    if (groups.length === 0) return { board: nextBoard, rngState: nextState, cascades }
    const cleared = [...new Set(groups.flatMap((group) => group.indices))].sort((left, right) => left - right)
    const filled = refill(nextBoard, new Set(cleared), nextState)
    cascades.push({ index: cascade, before: nextBoard, groups, cleared, after: filled.board })
    nextBoard = filled.board
    nextState = filled.state
  }
  if (sparkMatchGroups(nextBoard).length > 0) throw new Error('Spark Rival cascade exceeded its safety bound')
  return { board: nextBoard, rngState: nextState, cascades }
}

export function createSparkRivalBoard(state: number): { board: readonly SparkOrb[]; rngState: number } {
  const source = SPARK_ORBS.flatMap((orb) => Array.from({ length: 5 }, () => orb))
  let nextState = state
  for (let attempt = 0; attempt < 2_048; attempt += 1) {
    const shuffled = sparkShuffle(source, nextState)
    nextState = shuffled.state
    if (sparkMatchGroups(shuffled.items).length === 0) return { board: shuffled.items, rngState: nextState }
  }
  throw new Error('Spark Rival could not generate a match-free starting board')
}

export function countSparkOrbs(cascades: readonly SparkCascade[]): Record<SparkOrb, number> {
  const totals = Object.fromEntries(SPARK_ORBS.map((orb) => [orb, 0])) as Record<SparkOrb, number>
  for (const cascade of cascades) for (const group of cascade.groups) totals[group.orb] += group.indices.length
  return totals
}
